package ai.elizaresearch.alphaphone;
import android.content.Context;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class GmailDeliveryTest {
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 static JSONObject saved()throws Exception{return new JSONObject(AlphaCredentialStore.slots.get(GmailReconciliation.SLOT));}
 static class Transport implements GmailDelivery.Connections {
  List<String> paths=new ArrayList<>();int historyStatus=200;boolean staleDuringHistory;boolean wrongOwner;Runnable onUser;Queue<JSONObject> pages=new ArrayDeque<>();
  public HttpURLConnection open(URL url){paths.add(url.getFile());return new HttpURLConnection(url){public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}
   public int getResponseCode(){check("GET".equals(getRequestMethod()),"GET only");check(!getInstanceFollowRedirects(),"redirect disabled");check("Bearer secret".equals(getRequestProperty("Authorization")),"existing credential only");return url.getPath().endsWith("history")?historyStatus:200;}
   public InputStream getInputStream()throws IOException{try{JSONObject value;if(url.getPath().endsWith("history")){if(staleDuringHistory)AlphaCredentialStore.epoch="changed";value=pages.remove();}else if(url.getPath().endsWith("user")){if(onUser!=null)onUser.run();value=new JSONObject().put("success",true).put("data",new JSONObject().put("userId",wrongOwner?"other":"owner").put("organizationId","org"));}else value=new JSONObject().put("success",true).put("data",new JSONArray().put(new JSONObject().put("connectionId","grant").put("connected",true).put("grantedCapabilities",new JSONArray().put("google.gmail.triage"))));return new ByteArrayInputStream(value.toString().getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IOException(e);}}
  };}
 }
 static GmailDelivery setup(Transport t)throws Exception{AlphaCredentialStore.slots.clear();AlphaCredentialStore.owner="owner";AlphaCredentialStore.epoch="epoch";AlphaCredentialStore.provider="elizacloud";AlphaCredentialStore.slots.put("cloud:production",new JSONObject().put("credentialId","credential").put("token","secret").toString());return new GmailDelivery(new Context(),t);}
 static String configure(GmailDelivery delivery)throws Exception{delivery.configure(delivery.begin(),"credential","grant");return saved().getJSONObject("binding").getString("generation");}
 static JSONObject base()throws Exception{return GmailReconciliationTest.baseline("100");}
 public static void main(String[]args)throws Exception{
  Transport transport=new Transport();GmailDelivery delivery=setup(transport);String generation=configure(delivery);transport.pages.add(base());check(delivery.sync(generation,()->{}),"baseline complete job");check(saved().getString("historyId").equals("100"),"durable baseline");
  configure(delivery);check(saved().getString("historyId").equals("100")&&saved().getJSONObject("binding").getString("generation").equals(generation),"same native owner reconfiguration preserves cursor");
  long attempt=delivery.begin();delivery.resume();check(saved().getString("historyId").equals("100"),"resume during configure preserves cursor");delivery.configure(attempt,"credential","grant");
  transport.pages.add(GmailReconciliationTest.page("100","110","opaque token",GmailReconciliationTest.event("101","message-added","mail","INBOX","UNREAD")));transport.pages.add(GmailReconciliationTest.page("100","112",null));check(delivery.sync(generation,()->{}),"paged sync");check(transport.paths.stream().anyMatch(p->p.contains("startHistoryId=100&pageToken=opaque+token")),"original checkpoint and encoded continuation");check(saved().getString("historyId").equals("112")&&GmailNoticePoster.posts==1,"one native notice and final checkpoint");
  String notice=saved().getJSONObject("notices").keys().next();delivery.capture(notice);boolean[] unlocked={true};transport.onUser=()->unlocked[0]=false;
  try{delivery.pending(()->{if(!unlocked[0])throw new SecurityException("locked");});throw new AssertionError("locked response admitted");}catch(SecurityException expected){}
  check(saved().has("tap"),"lock during grant check retains tap");String token=saved().getJSONObject("tap").getString("token");try{delivery.consume(token,()->{throw new SecurityException("paused");});throw new AssertionError("paused consume admitted");}catch(SecurityException expected){}check(saved().has("tap"),"pause cannot consume unseen tap");transport.onUser=null;unlocked[0]=true;
  transport.historyStatus=404;check(delivery.sync(generation,()->{}),"unsupported not retry storm");check(delivery.status().getString("status").equals("unsupported"),"undeployed endpoint truthful");
  transport.historyStatus=200;transport.staleDuringHistory=true;transport.pages.add(GmailReconciliationTest.page("112","114",null,GmailReconciliationTest.event("113","message-added","stale","INBOX","UNREAD")));try{delivery.sync(generation,()->{});throw new AssertionError("stale read admitted");}catch(SecurityException expected){}check(saved().getString("historyId").equals("112")&&GmailNoticePoster.posts==1,"owner changed during I/O cannot publish or advance");
  AlphaCredentialStore.observer.changed();check(!AlphaCredentialStore.slots.containsKey(GmailReconciliation.SLOT)&&GmailNoticePoster.active.isEmpty(),"credential observer removes cursor and notifications");
  Transport wrong=new Transport();wrong.wrongOwner=true;GmailDelivery denied=setup(wrong);try{configure(denied);throw new AssertionError("wrong owner admitted");}catch(SecurityException expected){}check(!AlphaCredentialStore.slots.containsKey(GmailReconciliation.SLOT),"remote owner cannot configure");
  Transport direct=new Transport();GmailDelivery cerebras=setup(direct);check(cerebras.status().getString("status").equals("disabled"),"unconfigured Cloud provider can enable");AlphaCredentialStore.provider="cerebras";check(cerebras.status().getString("status").equals("provider-unsupported"),"direct provider reports its real blocker");try{configure(cerebras);throw new AssertionError("non-Cloud provider admitted");}catch(SecurityException expected){}check(!AlphaCredentialStore.slots.containsKey(GmailReconciliation.SLOT),"non-Cloud provider cannot configure");
  System.out.println("PASS Gmail delivery owner fences, durable pagination, startup continuity and unsupported deployment");
 }
}
